/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { BumpHuntScreen } from "../../src/bump-hunt/BumpHuntScreen.js";
import ColliderLabColors from "../../src/ColliderLabColors.js";
import { EnergyFrontierScreen } from "../../src/energy-frontier/EnergyFrontierScreen.js";
import { EventDisplayScreen } from "../../src/event-display/EventDisplayScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { ColliderLabPreferencesModel } from "../../src/preferences/ColliderLabPreferencesModel.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from colliderLabQueryParameters.
  const simPreferences = new ColliderLabPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new EventDisplayScreen({
      preferences: simPreferences,
      name: stringManager.getScreenNames().eventDisplayStringProperty,
      tandem: Tandem.ROOT.createTandem("eventDisplayScreen"),
      backgroundColorProperty: ColliderLabColors.backgroundColorProperty,
    }),
    new BumpHuntScreen({
      name: stringManager.getScreenNames().bumpHuntStringProperty,
      tandem: Tandem.ROOT.createTandem("bumpHuntScreen"),
      backgroundColorProperty: ColliderLabColors.backgroundColorProperty,
    }),
    new EnergyFrontierScreen({
      name: stringManager.getScreenNames().energyFrontierStringProperty,
      tandem: Tandem.ROOT.createTandem("energyFrontierScreen"),
      backgroundColorProperty: ColliderLabColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { ColliderLabColors, stringManager, simPreferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
